// GENERATED by packages/protocol/tools/known-cores.js from
// packages/core/tools/hash-core.js - do not edit by hand.
//
// The core hashes (sim_wasm_hash, sorted-source sha256) of reproducibly built
// core versions this client will let a player stake on (§5). A paying round
// naming any other core is refused by `coreIsKnownGood` (known-core.js).
const KNOWN_GOOD_CORE_HASHES = Object.freeze([
  'f33aa45c61db5f531fbf1b714c2da0fde031d84a14d7a9fde665a142d4828f3c',
  '5f3b517648bde43dca8c93938c45f4996242630f8cc173d1d940df89c4dd8e48',
  'ac526bca7c566fc3bf510ae3d9ac9b4326b18d47e40251912045474bc2bb4a0d',
]);

// ---- protocol/src/known-core.js
// A PAYING ROUND RUNS A CORE THIS CLIENT KNOWS, OR IT IS REFUSED.
//
// Section 5 (v4.6): "The sim_wasm_hash is chosen by the round creator, so the
// client must not accept it blindly. For real-money rounds the client MUST
// verify the hash against its known-good list of reproducibly built core
// versions, and MUST refuse - or require an explicit, clearly worded override -
// for unknown hashes. Otherwise a creator could publish a round running a
// backdoored core." This client refuses. There is no override: no flag, no
// query parameter, nothing that lets an unknown core through.
